def transform(grid):
    h, w = len(grid), len(grid[0])

    # The first 5 in the top row marks the separator after the first n-by-n tile.
    n = grid[0].index(5)
    starts = range(0, w - n + 1, n + 1)
    data_top = n + 1
    label_row = 2 * n + 3

    palette = {}
    for start in starts:
        tile = [row[start:start + n] for row in grid[:n]]
        colors = [v for row in tile for v in row if v != 0 and v != 5]
        if not colors:
            continue
        color = max(set(colors), key=colors.count)
        marker_col = start + n // 2
        label = grid[label_row][marker_col] if label_row < h else 0
        palette[color] = (tile, label)

    out = [[0] * (n * n) for _ in range(n * n)]
    for start in starts:
        for r in range(n):
            for c in range(n):
                color = grid[data_top + r][start + c]
                if color not in palette:
                    continue
                tile, label = palette[color]
                for tr in range(n):
                    for tc in range(n):
                        if tile[tr][tc] != 0:
                            out[r * n + tr][c * n + tc] = label
    return out
